    table_set(T,k,v,9);yield a;}].v);commit;}

module Persist;
table T capacity 2 { key id: id64<T>; col value: u64; }
transition put(k: id64<T>, value: u64) reads [] writes [T[k].value]
  require live: table_exists(T,k);
  body { table_set(T,k,value,value); commit; }

module Persist;
table T capacity 2 { key id: id64<T>; col value: u64; }
transition put(k: id64<T>, value: u64) reads [] writes [T[k].value]
  require live: table_exists(T,k);
  body { table_set(T,k,value,0); commit; }

module Persist;
table T capacity 2 { key id: id64<T>; col value: i64; }
invariant nonnegative { forall k in T : ge(T[k].value,0); }
transition put(k: id64<T>, value: u64) reads [] writes [T[k].value]
  require live: table_exists(T,k);
  body { table_set(T,k,value,value); commit; }

module Persist;
table T capacity 2 { key id: id64<T>; col value: i64; }
invariant nonnegative { forall k in T : ge(T[k].value,0); }
transition put(k: id64<T>, value: i64) reads [] writes [T[k].value]
  require nonnegative: ge(value,0);
  require live: table_exists(T,k);
  body { table_set(T,k,value,value); commit; }

module Persist;
table T capacity 2 { key id: id64<T>; col value: u64; }
invariant zero { forall k in T : eq(T[k].value,0); }
transition put(k: id64<T>, value: u64) reads [] writes [T[k].value]
  require live: table_exists(T,k);
  body { table_set(T,k,value,value); commit; }

